cat > src/server/repositories/issue-dependency-repository.ts <<'EOF'
/**
 * "Blocked by" links between issues. Every method takes `orgId` first; a link
 * is only ever read or written inside the organization that owns both ends.
 *
 * Must call (do not reimplement): livePredicate, orgPredicate
 */
import { and, asc, eq, inArray, notInArray } from "drizzle-orm";
import { getDb, issueDependencies, issues } from "@/server/db";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { toIsoTimestamp } from "@/types/common";
import { livePredicate, orgPredicate } from "./base-repository";
import { toIssue, toIssueDependency } from "./_mappers";
import { listLabelsForIssues } from "./label-repository";
import type { IssueId, OrgId, UserId } from "@/types/common";
import type { Issue, IssueDependency } from "@/types/issue";

export async function findDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
): Promise<IssueDependency | null> {
  const row = getDb()
    .select()
    .from(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .get();
  return row ? toIssueDependency(row) : null;
}

/** Idempotent: an existing link is returned as-is, never duplicated. */
export async function insertDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
  createdBy: UserId,
): Promise<IssueDependency> {
  const inserted = getDb()
    .insert(issueDependencies)
    .values({
      orgId,
      issueId,
      blockerId,
      createdBy,
      createdAt: toIsoTimestamp(new Date()),
    })
    .onConflictDoNothing()
    .returning()
    .get();
  if (inserted) return toIssueDependency(inserted);

  const existing = await findDependency(orgId, issueId, blockerId);
  if (!existing) throw new Error("Issue dependency insert produced no row");
  return existing;
}

/** Resolves `true` when a link existed and was removed. */
export async function deleteDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
): Promise<boolean> {
  const rows = getDb()
    .delete(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .returning({ issueId: issueDependencies.issueId })
    .all();
  return rows.length > 0;
}

/**
 * The blockers of every issue in `issueIds`, archived or not — the raw edges,
 * used to walk the graph when checking a new link for a cycle.
 */
export async function listBlockerIdsOf(
  orgId: OrgId,
  issueIds: readonly IssueId[],
): Promise<readonly IssueId[]> {
  if (issueIds.length === 0) return [];

  const rows = getDb()
    .select({ blockerId: issueDependencies.blockerId })
    .from(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        inArray(issueDependencies.issueId, [...issueIds]),
      ),
    )
    .all();
  return rows.map((row) => row.blockerId as IssueId);
}

/** Live blockers of one issue (open or closed), by issue number ascending. */
export async function listBlockers(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select({ issue: issues })
    .from(issueDependencies)
    .innerJoin(
      issues,
      and(
        eq(issues.id, issueDependencies.blockerId),
        orgPredicate(issues.orgId, orgId),
      ),
    )
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
        livePredicate(issues.archivedAt, {}),
      ),
    )
    .orderBy(asc(issues.number), asc(issues.id))
    .all();

  const labels = await listLabelsForIssues(
    orgId,
    rows.map((row) => row.issue.id as IssueId),
  );
  return rows.map(({ issue }) =>
    toIssue(issue, (labels[issue.id] ?? []).map((label) => label.id)),
  );
}

/** Ids of the blockers that are still open: live and not done/canceled. */
export async function listOpenBlockerIds(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly IssueId[]> {
  const rows = getDb()
    .select({ id: issues.id })
    .from(issueDependencies)
    .innerJoin(
      issues,
      and(
        eq(issues.id, issueDependencies.blockerId),
        orgPredicate(issues.orgId, orgId),
      ),
    )
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
        livePredicate(issues.archivedAt, {}),
        notInArray(issues.status, [...CLOSED_ISSUE_STATUSES]),
      ),
    )
    .orderBy(asc(issues.number), asc(issues.id))
    .all();
  return rows.map((row) => row.id as IssueId);
}

/** Every issue that `blockerId` blocks, whatever its own state. */
export async function listBlockedIssues(
  orgId: OrgId,
  blockerId: IssueId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select({ issue: issues })
    .from(issueDependencies)
    .innerJoin(
      issues,
      and(
        eq(issues.id, issueDependencies.issueId),
        orgPredicate(issues.orgId, orgId),
      ),
    )
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .orderBy(asc(issues.number), asc(issues.id))
    .all();
  return rows.map(({ issue }) => toIssue(issue));
}
