/**
 * Tells an assignee when the last open blocker of their issue closes.
 *
 * Must call (do not reimplement): subscribe, notify
 */
import { subscribe } from "@/lib/event-bus";
import * as dependencyRepo from "@/server/repositories/issue-dependency-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { notify } from "./notification-service";
import type { IssueId, OrgId, UserId } from "@/types/common";
import type { IssueStatus } from "@/types/issue";
import type { Unsubscribe } from "@/types/event";

function isClosedStatus(status: IssueStatus): boolean {
  return CLOSED_ISSUE_STATUSES.includes(status);
}

/**
 * For each issue blocked by any of `closedIds` that is itself live and open,
 * has an assignee and now has no open blocker left, sends one
 * `issue_unblocked` notification. Blocked issues are de-duplicated across
 * `closedIds` so a batch that closes several blockers of one issue (a project
 * archive) still notifies once.
 */
async function notifyUnblocked(
  orgId: OrgId,
  closedIds: readonly IssueId[],
  actorId: UserId | null,
): Promise<void> {
  const seen = new Set<IssueId>();

  for (const closedId of closedIds) {
    for (const issue of await dependencyRepo.listBlockedIssues(orgId, closedId)) {
      if (seen.has(issue.id)) continue;
      seen.add(issue.id);

      if (
        issue.archivedAt !== null ||
        isClosedStatus(issue.status) ||
        issue.assigneeId === null
      ) {
        continue;
      }
      if ((await dependencyRepo.listOpenBlockerIds(orgId, issue.id)).length > 0) {
        continue;
      }

      await notify(orgId, "issue_unblocked", [issue.assigneeId], {
        title: "An issue you are assigned to is unblocked",
        body: `"${issue.title}" no longer has any open blockers`,
        href: `/issues/${issue.id}`,
        actorId,
      });
    }
  }
}

/**
 * A blocker goes from open to closed when its status moves to `done` or
 * `canceled`, or when it is archived while still open. Closed→closed changes
 * and reopenings never notify.
 */
export function registerIssueUnblockListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("issue.status_changed", async (payload) => {
      if (isClosedStatus(payload.from) || !isClosedStatus(payload.to)) return;
      await notifyUnblocked(payload.orgId, [payload.issueId], payload.actorId);
    }),
    subscribe("issue.archived", async (payload) => {
      // Archiving leaves `status` alone, so it still says what the issue was.
      const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
      if (issue === null || isClosedStatus(issue.status)) return;
      await notifyUnblocked(payload.orgId, [payload.issueId], payload.actorId);
    }),
    subscribe("project.archived", async (payload) => {
      const archivedOpen = payload.archivedOpenIssueIds ?? [];
      if (archivedOpen.length === 0) return;
      await notifyUnblocked(payload.orgId, archivedOpen, payload.actorId);
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}
