import type { Issue, IssueDependency } from "@/types/issue";
import type { Actor } from "@/types/member";

/**
 * Raised when an issue is moved to `done` while blockers are still open.
 * `blockerIds` names exactly the open ones, by issue number ascending.
 */
export class IssueBlockedError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly blockerIds: readonly IssueId[]) {
    super(
      `Issue cannot be completed while ${blockerIds.length} blocker(s) are open: ${blockerIds.join(", ")}`,
    );
    this.name = "IssueBlockedError";
  }
}

/** Raised when a new link would make an issue (transitively) block itself. */
class DependencyCycleError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly issueId: IssueId,
    readonly blockerId: IssueId,
  ) {
    super(
      issueId === blockerId
        ? `Issue ${issueId} cannot be blocked by itself`
        : `Issue ${issueId} cannot be blocked by ${blockerId}: that would create a dependency cycle`,
    );
    this.name = "DependencyCycleError";
  }
}

interface BlockerInput {
  orgId: OrgId;
  issueId: IssueId;
  blockerId: IssueId;
}

/**
 * Records "`issueId` is blocked by `blockerId`". Needs the permission to edit
 * the blocked issue. Both issues must be live, and the link must keep the
 * graph acyclic. Re-adding an existing link returns it unchanged.
 */
export async function addBlocker(
  actor: Actor,
  input: BlockerInput,
): Promise<IssueDependency> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  const blocker = requireFound(
    await issueRepo.findIssueById(input.orgId, input.blockerId),
    "Issue",
    input.blockerId,
  );
  assertCan(actor, "issue:update", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);
  assertNotArchived("Issue", blocker.id, blocker);

  if (issue.id === blocker.id) {
    throw new DependencyCycleError(issue.id, blocker.id);
  }

  const result = await dependencyRepo.insertDependencyUnlessCyclic(
    input.orgId,
    issue.id,
    blocker.id,
    actor.userId,
  );
  if (result.outcome === "cycle") {
    throw new DependencyCycleError(issue.id, blocker.id);
  }

  return result.dependency;
}

/**
 * Deletes the link; `true` when there was one to delete. Removing a link is
 * an edit of the blocked issue, so it needs the same permission as adding one.
